import path from "node:path";
import postgres from "postgres";
import { drizzle } from "drizzle-orm/postgres-js";
import { migrate } from "drizzle-orm/postgres-js/migrator";

/** Applies the SQL files in ./drizzle (generated by `npm run db:generate`). Safe to run on every start. */
export async function runMigrations() {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL is not set");
  const sql = postgres(url, { max: 1, onnotice: () => {} });
  try {
    await migrate(drizzle(sql), { migrationsFolder: path.join(process.cwd(), "drizzle") });
    console.log("[db] migrations up to date");
  } finally {
    await sql.end();
  }
}

/** After a reboot Postgres can still be starting up: retry for ~2 minutes, then exit so Docker restarts the app. */
export async function runMigrationsWithRetry() {
  for (let attempt = 1; ; attempt++) {
    try {
      return await runMigrations();
    } catch (err) {
      if (attempt >= 24) {
        console.error("[db] database not reachable, exiting so Docker restarts the app", err);
        process.exit(1);
      }
      console.warn(`[db] database not ready (attempt ${attempt}), retrying in 5s`);
      await new Promise((r) => setTimeout(r, 5000));
    }
  }
}
